var backgroundFrag = "#include \"_prelude_fog.fragment.glsl\"\n#include \"_prelude_lighting.glsl\"\n\nuniform vec4 u_color;\nuniform float u_opacity;\n\n#ifdef LIGHTING_3D_MODE\nin vec4 v_color;\n#endif\n\nvoid main() {\n    vec4 out_color;\n#ifdef LIGHTING_3D_MODE\n    out_color = v_color;\n#else\n    out_color = u_color;\n#endif\n#ifdef FOG\n    out_color = fog_dither(fog_apply_premultiplied(out_color, v_fog_pos));\n#endif\n\n    glFragColor = out_color * u_opacity;\n\n#ifdef OVERDRAW_INSPECTOR\n    glFragColor = vec4(1.0);\n#endif\n\n    HANDLE_WIREFRAME_DEBUG;\n}\n";

var backgroundVert = "#include \"_prelude_fog.vertex.glsl\"\n#include \"_prelude_lighting.glsl\"\n\nin vec2 a_pos;\n\nuniform mat4 u_matrix;\n\n#ifdef LIGHTING_3D_MODE\nuniform mediump vec4 u_color;\nout vec4 v_color;\nuniform float u_emissive_strength;\n#endif\n\nvoid main() {\n    gl_Position = u_matrix * vec4(a_pos, 0, 1);\n\n#ifdef LIGHTING_3D_MODE\n    v_color = apply_lighting_with_emission_ground(u_color, u_emissive_strength);\n#endif\n#ifdef FOG\n    v_fog_pos = fog_position(a_pos);\n#endif\n}\n";

var backgroundPatternFrag = "#include \"_prelude_fog.fragment.glsl\"\n#include \"_prelude_lighting.glsl\"\n\nuniform vec2 u_pattern_tl;\nuniform vec2 u_pattern_br;\nuniform vec2 u_texsize;\nuniform float u_opacity;\nuniform float u_emissive_strength;\n\nuniform sampler2D u_image;\n\nin highp vec2 v_pos;\n\nvoid main() {\n    highp vec2 imagecoord = mod(v_pos, 1.0);\n    highp vec2 pos = mix(u_pattern_tl / u_texsize, u_pattern_br / u_texsize, imagecoord);\n    vec4 out_color = textureLodCustom(u_image, pos, v_pos);\n\n#ifdef LIGHTING_3D_MODE\n    out_color = apply_lighting_with_emission_ground(out_color, u_emissive_strength);\n#endif\n#ifdef FOG\n    out_color = fog_dither(fog_apply_premultiplied(out_color, v_fog_pos));\n#endif\n\n    glFragColor = out_color * u_opacity;\n\n#ifdef OVERDRAW_INSPECTOR\n    glFragColor = vec4(1.0);\n#endif\n\n    HANDLE_WIREFRAME_DEBUG;\n}\n";

var backgroundPatternVert = "#include \"_prelude_fog.vertex.glsl\"\n\nuniform mat4 u_matrix;\nuniform vec2 u_pattern_size;\nuniform vec2 u_pixel_coord_upper;\nuniform vec2 u_pixel_coord_lower;\nuniform vec2 u_pattern_units_to_pixels;\n\nin vec2 a_pos;\n\nout highp vec2 v_pos;\n\nvoid main() {\n    gl_Position = u_matrix * vec4(a_pos, 0, 1);\n\n    v_pos = get_pattern_pos(u_pixel_coord_upper, u_pixel_coord_lower, u_pattern_size, u_pattern_units_to_pixels, a_pos);\n\n#ifdef FOG\n    v_fog_pos = fog_position(a_pos);\n#endif\n}\n";

var buildingFrag = "#include \"_prelude_fog.fragment.glsl\"\n#include \"_prelude_shadow.fragment.glsl\"\n#include \"_prelude_lighting.glsl\"\n\nconst float window_depth = 0.5; // meters\nconst float ao_radius = 0.2; // meters\n\nin vec4 v_color;\nin highp vec3 v_normal;\nin highp vec3 v_pos;\n\n#ifdef BUILDING_FAUX_FACADE\nin lowp float v_faux_facade;\nin highp float v_faux_facade_ed;\nin highp vec2 v_faux_facade_window;\nin highp vec2 v_faux_facade_floor;\nin highp vec2 v_faux_facade_range;\nin highp float v_aspect;\nin highp vec3 v_tbn_0;\nin highp vec3 v_tbn_1;\nin highp vec3 v_tbn_2;\nin highp vec4 v_faux_color_emissive;\nuniform float u_faux_facade_ao_intensity;\n#endif\n\n#ifdef RENDER_SHADOWS\nin highp vec4 v_pos_light_view_0;\nin highp vec4 v_pos_light_view_1;\nin float v_depth_shadows;\n#endif\n\nuniform lowp float u_opacity;\nuniform vec3 u_camera_pos; // in tile coordinates\nuniform highp float u_tile_to_meter;\n\nuniform float u_facade_emissive_chance;\n\nvec3 linearTosRGB(in vec3 color) {\n    return pow(color, vec3(1./2.2));\n}\n\n#ifdef BUILDING_FAUX_FACADE\n// From https://www.shadertoy.com/view/4djSRW by David Hoskins.\n// A shader Hash function that is the same on all systems and doesn't rely on trig functions.\nfloat hash12(in vec2 p) {\n\tvec3 p3  = fract(vec3(p.xyx) * 0.1031);\n    p3 += dot(p3, p3.yzx + 33.33);\n    return fract((p3.x + p3.y) * p3.z);\n}\n\nfloat min3(in vec3 v) {\n    return min(min(v.x, v.y), v.z);\n}\n\n// q is in meters.\nvec2 get_uv_mask_id(in vec2 q, out float mask, out vec2 id) {\n    vec2 p = q;\n    // Only shade with facades if in range.\n    mask = step(v_faux_facade_range.x, p.y) * step(p.y, v_faux_facade_range.y);\n    // Compute UVs for windows.\n    p.y = p.y - v_faux_facade_range.x;\n    vec2 uv = modf(p / v_faux_facade_floor, id);\n\n    vec4 d = (v_faux_facade_floor.xyxy + vec4(-v_faux_facade_window, v_faux_facade_window)) * 0.5;\n    vec4 edge = d / v_faux_facade_floor.xyxy;\n\n    vec2 m = step(edge.xy, uv) * step(uv, edge.zw);\n    mask *= m.x * m.y;\n    uv -= vec2(0.5);\n    uv *= vec2(0.5) / (vec2(0.5) - edge.xy);\n    uv += vec2(0.5);\n    return uv;\n}\n\nfloat ray_unit_box(in vec3 ray_o, in vec3 ray_d, in vec3 bmin, in vec3 bmax) {\n    vec3 planes = mix(bmin, bmax, step(0.0, ray_d));\n    vec3 t = (planes - ray_o) / ray_d;\n    return min3(t);\n}\n\nfloat get_emissive(in vec2 id) {\n    if (u_facade_emissive_chance > 0.0) {\n        return (step(hash12(id), u_facade_emissive_chance) + 0.05) * v_faux_color_emissive.a;\n    }\n    return 0.0;\n}\n\n// v.x is in [-v_faux_facade_window.x / 2, v_faux_facade_window.x / 2] range.\n// v.y is in [-v_faux_facade_window.y / 2, v_faux_facade_window.y / 2] range.\n// v.z is in [-window_depth / 2, window_depth / 2] range.\n// All values are in meters.\nvec3 get_shade_info(in vec3 v,\n                    in vec3 v_normalized,\n                    in vec3 color,\n                    in vec2 id,\n                    in mat3 tbn,\n                    inout vec3 out_normal,\n                    inout float out_emissive) {\n    vec3 out_color = color;\n    vec3 abs_v = abs(v_normalized);\n    bool x_major = abs_v.x >= abs_v.y && abs_v.x >= abs_v.z;\n    bool y_major = abs_v.y >= abs_v.x && abs_v.y >= abs_v.z;\n    bool z_major = abs_v.z >= abs_v.x && abs_v.z >= abs_v.y;\n#if 0 // For debugging only.\n    if (x_major) {\n        out_color = v.x > 0.0 ? vec3(1.0, 0.0, 0.0) : vec3(0.0, 1.0, 1.0);\n    } else if (y_major) {\n        out_color = v.y > 0.0 ? vec3(0.0, 1.0, 0.0) : vec3(1.0, 0.0, 1.0);\n    } else if (z_major) {\n        out_color = v.z > 0.0 ? vec3(0.0, 0.0, 1.0) : vec3(1.0, 1.0, 0.0);\n    }\n    out_emissive = 1.0;\n#else\n    if (x_major) {\n        out_normal = sign(v.x) * tbn[0];\n    } else if (y_major) {\n        out_normal = vec3(0.0, 0.0, -sign(v.y));\n    } else if (z_major) {\n        out_color = v_faux_color_emissive.rgb;\n        out_emissive = v.z <= 0.0 ? get_emissive(id) : out_emissive;\n    }\n\n    float ao = 1.0;\n    if (u_faux_facade_ao_intensity > 0.0) {\n        vec4 ao_range = v_faux_facade_window.xxyy * 0.5 - vec4(0, ao_radius, 0, ao_radius);\n        vec2 ao_range_z = vec2(window_depth * 0.5) - vec2(0.0, ao_radius);\n        if (x_major || y_major) {\n            ao *= smoothstep(-ao_range_z.x, -ao_range_z.y, v.z);\n        } else if (z_major) {\n            ao *= smoothstep(-ao_range.x, -ao_range.y, v.x) * (1.0 - smoothstep(ao_range.y, ao_range.x, v.x));\n            ao *= smoothstep(-ao_range.z, -ao_range.w, v.y) * (1.0 - smoothstep(ao_range.w, ao_range.z, v.y));\n        }\n        ao = mix(1.0, min(1.0, ao + 0.25), u_faux_facade_ao_intensity);\n    }\n\n    out_color *= ao;\n#endif\n    return out_color;\n}\n#endif // BUILDING_FAUX_FACADE\n\n\nvec3 apply_lighting_linear(in vec3 color, in vec3 normal, in float dir_factor) {\n    float ambient_directional_factor = calculate_ambient_directional_factor(normal);\n    vec3 ambient_contrib = ambient_directional_factor * u_lighting_ambient_color;\n    vec3 directional_contrib = u_lighting_directional_color * dir_factor;\n    return color * (ambient_contrib + directional_contrib);\n}\n\nvoid main() {\n    vec3 normal = normalize(v_normal);\n    vec3 base_color = v_color.rgb;\n    float emissive = v_color.a;\n\n#ifdef BUILDING_FAUX_FACADE\n    if (v_faux_facade > 0.0) {\n        mat3 tbn = mat3(v_tbn_0, v_tbn_1, v_tbn_2);\n\n        // v_pos.z is in meters.\n        vec3 v = vec3(v_pos.xy, v_pos.z / u_tile_to_meter) - u_camera_pos;\n        vec3 view_tangent = transpose(tbn) * v; // TBN guaranteed to be orthonormal, so we can use transpose.\n\n        vec2 q = vec2(v_faux_facade_ed, v_pos.z);\n        float mask = 0.0;\n        vec2 id = vec2(0.0);\n        vec2 uv = get_uv_mask_id(q, mask, id);\n        uv *= v_faux_facade_window;\n\n        // Perform ray intersection with a box defined by bmin and bmax.\n        vec3 bmin = vec3(0.0, 0.0, -window_depth);\n        vec3 bmax = bmin + vec3(v_faux_facade_window, window_depth);\n        vec3 ray_o = vec3(uv, 0.0);\n        vec3 ray_d = normalize(view_tangent);\n        float t_min = ray_unit_box(ray_o, ray_d, bmin, bmax);\n        vec3 hit = ray_o + t_min * ray_d;\n\n        vec3 r = vec3(v_faux_facade_window, -window_depth);\n        hit -= r * 0.5;\n        vec3 normalized = hit / r;\n\n        vec3 out_normal = normal;\n        float out_emissive = emissive;\n        vec3 room_color = get_shade_info(hit, normalized, base_color, id, tbn, out_normal, out_emissive);\n\n        base_color = mix(base_color, room_color, mask);\n        normal = mix(normal, out_normal, mask);\n        emissive = mix(emissive, out_emissive, mask);\n    }\n#endif // BUILDING_FAUX_FACADE\n\n    vec4 color = vec4(base_color, 1.0);\n    vec3 xy_flipped_normal = vec3(-normal.xy, normal.z);\n\n    float shadowed_lighting_factor = 0.0;\n#ifdef RENDER_SHADOWS\n    shadowed_lighting_factor = shadowed_light_factor_normal(xy_flipped_normal, v_pos_light_view_0, v_pos_light_view_1, v_depth_shadows);\n#else\n    shadowed_lighting_factor = dot(normal, u_lighting_directional_dir);\n#endif\n\n    color.rgb = apply_lighting_linear(color.rgb, xy_flipped_normal, shadowed_lighting_factor);\n    color.rgb = mix(color.rgb, base_color.rgb, emissive);\n    \n#ifdef FOG\n    color = fog_dither(fog_apply_premultiplied(color, v_fog_pos, v_pos.z));\n#endif\n\n    color.rgb = linearTosRGB(color.rgb);\n    color *= u_opacity;\n\n#ifdef INDICATOR_CUTOUT\n    color = applyCutout(color, v_pos.z);\n#endif\n\n    glFragColor = color; \n\n#ifdef DEBUG_SHOW_NORMALS\n    color.rgb = xy_flipped_normal * 0.5 + vec3(0.5, 0.5, 0.5);\n    color.a = 1.0;\n    glFragColor = color;\n#endif\n\n#ifdef OVERDRAW_INSPECTOR\n    glFragColor = vec4(1.0);\n#endif\n\n    HANDLE_WIREFRAME_DEBUG;\n}\n";

var buildingVert = "#include \"_prelude_fog.vertex.glsl\"\n#include \"_prelude_shadow.vertex.glsl\"\n\nin vec3 a_pos_3f;\nin vec3 a_normal_3;\nin vec3 a_centroid_3;\n\nin vec4 a_faux_facade_data;\nin vec2 a_faux_facade_vertical_range;\n\nuniform mat4 u_matrix;\nuniform mat4 u_normal_matrix;\nuniform highp float u_tile_to_meter;\n\nout vec4 v_color;\nout vec3 v_normal;\nout highp vec3 v_pos;\n\n#ifdef BUILDING_FAUX_FACADE\nout lowp float v_faux_facade;\nout highp float v_faux_facade_ed;\nout highp vec2 v_faux_facade_window;\nout highp vec2 v_faux_facade_floor;\nout highp vec2 v_faux_facade_range;\nout highp float v_aspect;\nout highp vec3 v_tbn_0;\nout highp vec3 v_tbn_1;\nout highp vec3 v_tbn_2;\nout highp vec4 v_faux_color_emissive;\n#endif\n\n#ifdef RENDER_SHADOWS\nuniform mat4 u_light_matrix_0;\nuniform mat4 u_light_matrix_1;\nout highp vec4 v_pos_light_view_0;\nout highp vec4 v_pos_light_view_1;\nout float v_depth_shadows;\n#endif\n\nconst float MAX_UINT_16 = 65535.0;\nconst float MAX_INT_16 = 32767.0;\nconst float MAX_UINT_8 = 255.0;\nconst float TWO_POW_8 = 256.0;\n\nvec3 sRGBToLinear(vec3 srgbIn) {\n    return pow(srgbIn, vec3(2.2));\n}\n\n#ifdef BUILDING_FAUX_FACADE\nmat3 get_tbn(in vec3 normal) {\n    const vec3 bitangent = vec3(0.0, 0.0, 1.0);\n    vec3 tangent = normalize(vec3(normal.y, -normal.x, 0.0)); // -cross(bitangent, normal);\n    return mat3(tangent, bitangent, normal);\n}\n#endif\n#pragma mapbox: define-attribute-vertex-shader-only highp vec2 part_color_emissive\n#pragma mapbox: define-attribute-vertex-shader-only highp vec2 faux_facade_color_emissive\n\nvoid main() {\n    #pragma mapbox: initialize-attribute-custom highp vec2 part_color_emissive\n    #pragma mapbox: initialize-attribute-custom highp vec2 faux_facade_color_emissive\n\n    vec4 color_emissive = decode_color(part_color_emissive);\n    v_color = vec4(sRGBToLinear(color_emissive.rgb), color_emissive.a);\n\n    vec3 a_normal_3f = a_normal_3 / MAX_INT_16;\n    v_normal = vec3(u_normal_matrix * vec4(a_normal_3f, 0.0));\n\n    float hidden = 0.0;\n    \n#ifdef BUILDING_FAUX_FACADE\n    v_faux_facade = a_faux_facade_data.x;\n    if (v_faux_facade > 0.0) {\n        v_faux_facade_ed = a_faux_facade_data.x  * u_tile_to_meter;\n\n        float window_x_perc = floor(a_faux_facade_data.y / TWO_POW_8);\n        float window_y_perc = a_faux_facade_data.y - TWO_POW_8 * window_x_perc;\n        vec2 window_perc = vec2(window_x_perc, window_y_perc) / MAX_UINT_8;\n\n        v_faux_facade_floor = (a_faux_facade_data.zw / MAX_UINT_16 * EXTENT) * u_tile_to_meter;\n        v_faux_facade_window = window_perc * v_faux_facade_floor;\n\n        v_faux_facade_range = (a_faux_facade_vertical_range / MAX_UINT_16 * EXTENT) * u_tile_to_meter;\n\n        v_aspect = v_faux_facade_window.x / v_faux_facade_window.y;\n\n        mat3 tbn = get_tbn(normalize(v_normal));\n        v_tbn_0 = tbn[0];\n        v_tbn_1 = tbn[1];\n        v_tbn_2 = tbn[2];\n\n        v_faux_color_emissive = decode_color(faux_facade_color_emissive);\n        v_faux_color_emissive.rgb = sRGBToLinear(v_faux_color_emissive.rgb);\n    }\n#endif\n    v_pos = a_pos_3f;\n\n#ifdef RENDER_CUTOFF\n    vec4 ground = u_matrix * vec4(a_centroid_3, 1.0);\n    v_cutoff_opacity = cutoff_opacity(u_cutoff_params, ground.z);\n    hidden = float(v_cutoff_opacity == 0.0);\n    v_pos.z *= v_cutoff_opacity;\n#endif\n\n#ifdef RENDER_SHADOWS\n    vec3 shadow_pos = v_pos;\n#ifdef NORMAL_OFFSET\n    vec3 offset = shadow_normal_offset_model(v_normal);\n    shadow_pos += offset * shadow_normal_offset_multiplier0();\n#endif\n    v_pos_light_view_0 = u_light_matrix_0 * vec4(shadow_pos, 1.0);\n    v_pos_light_view_1 = u_light_matrix_1 * vec4(shadow_pos, 1.0);\n    v_depth_shadows = gl_Position.w;\n#endif\n\n#ifdef FOG\n    v_fog_pos = fog_position(v_pos);\n#endif\n\n    gl_Position = mix(u_matrix * vec4(v_pos, 1), AWAY, hidden);\n}\n";

var buildingBloomFrag = "in vec4 v_color_emissive;\n\n#pragma mapbox: define-attribute highp vec4 bloom_attenuation\n#pragma mapbox: initialize-attribute highp vec4 bloom_attenuation\n\nfloat saturate(float val) {\n    return clamp(val, 0.0, 1.0);\n}\n\nvoid main() {\n    float emission = v_color_emissive.a;\n    float opacity = 1.0;\n\n#ifdef HAS_ATTRIBUTE_a_bloom_attenuation\n    // a_bloom_attenuation is used to pass information about light geometry.\n    // calculate distance to line segment, multiplier 1.3 additionally deattenuates towards extruded corners.\n    float distance = length(vec2(1.3 * max(0.0, abs(bloom_attenuation.x) - bloom_attenuation.z), bloom_attenuation.y));\n    distance +=  mix(0.5, 0.0, clamp(emission - 1.0, 0.0, 1.0));\n    opacity *= saturate(1.0 - distance * distance);\n#endif\n\n    glFragColor = vec4(v_color_emissive.rgb, 1.0) * opacity;\n}\n";

var buildingBloomVert = "in vec3 a_pos_3f;\n\n#pragma mapbox: define-attribute-vertex-shader-only highp vec2 part_color_emissive\n#pragma mapbox: define-attribute highp vec4 bloom_attenuation\n\nout vec4 v_color_emissive;\n\nuniform mat4 u_matrix;\n\nvec3 sRGBToLinear(vec3 srgbIn) {\n    return pow(srgbIn, vec3(2.2));\n}\n\nvoid main() {\n    #pragma mapbox: initialize-attribute-custom highp vec2 part_color_emissive\n    #pragma mapbox: initialize-attribute highp vec4 bloom_attenuation\n\n#ifdef HAS_ATTRIBUTE_a_part_color_emissive\n    vec4 color_emissive = decode_color(part_color_emissive);\n    float part_emissive = color_emissive.a * 5.0; // The emissive value was compressed from [0,5] to [0,1]\n    v_color_emissive = vec4(sRGBToLinear(color_emissive.rgb), part_emissive);\n#else\n    v_color_emissive = vec4(1.0);\n#endif\n\n    gl_Position = u_matrix * vec4(a_pos_3f, 1.0);\n}\n";

