var debugVert = "#include \"_prelude_terrain.vertex.glsl\"\n\nin vec2 a_pos;\n#ifdef PROJECTION_GLOBE_VIEW\nin vec3 a_pos_3;\n#endif\nout vec2 v_uv;\n\nuniform mat4 u_matrix;\nuniform float u_overlay_scale;\n\nvoid main() {\n    // This vertex shader expects a EXTENT x EXTENT quad,\n    // The UV co-ordinates for the overlay texture can be calculated using that knowledge\n    float h = elevation(a_pos);\n    v_uv = a_pos / 8192.0;\n#ifdef PROJECTION_GLOBE_VIEW\n    gl_Position = u_matrix * vec4(a_pos_3 + elevationVector(a_pos) * h, 1);\n#else\n    gl_Position = u_matrix * vec4(a_pos * u_overlay_scale, h, 1);\n#endif\n}\n";

var fillFrag = "#include \"_prelude_fog.fragment.glsl\"\n#include \"_prelude_lighting.glsl\"\n#include \"_prelude_shadow.fragment.glsl\"\n\n#pragma mapbox: define highp vec4 color\n#pragma mapbox: define lowp float opacity\n\nuniform float u_emissive_strength;\n\n#ifdef RENDER_SHADOWS\nuniform vec3 u_ground_shadow_factor;\n\nin highp vec4 v_pos_light_view_0;\nin highp vec4 v_pos_light_view_1;\nin highp float v_depth;\n#endif\n\n#ifdef ELEVATED_ROADS\nin highp float v_road_z_offset;\n#endif\n\n#ifdef INDICATOR_CUTOUT\nin highp float v_z_offset;\n#endif\n\nvoid main() {\n    #pragma mapbox: initialize highp vec4 color\n    #pragma mapbox: initialize lowp float opacity\n\n    vec4 out_color = color;\n\n#ifdef LIGHTING_3D_MODE\n    out_color = apply_lighting_with_emission_ground(out_color, u_emissive_strength);\n#ifdef RENDER_SHADOWS\n    float light = shadowed_light_factor(v_pos_light_view_0, v_pos_light_view_1, v_depth);\n    out_color.rgb *= mix(u_ground_shadow_factor, vec3(1.0), light);\n#endif // RENDER_SHADOWS\n#endif // LIGHTING_3D_MODE\n\n#ifdef FOG\n    out_color = fog_dither(fog_apply_premultiplied(out_color, v_fog_pos));\n#endif\n\n    out_color *= opacity;\n\n#ifdef INDICATOR_CUTOUT\n    // apply cutout if the fragment is not an underground polygon (no need)\n    if (v_z_offset >= 0.0) {\n        out_color = applyCutout(out_color, v_z_offset);\n    }\n#endif\n\n#ifdef FEATURE_CUTOUT\n    out_color = apply_feature_cutout(out_color, gl_FragCoord);\n#endif\n\n    glFragColor = out_color;\n\n#ifdef OVERDRAW_INSPECTOR\n    glFragColor = vec4(1.0);\n#endif\n\n    HANDLE_WIREFRAME_DEBUG;\n}\n\n";

var fillVert = "#include \"_prelude_fog.vertex.glsl\"\n#include \"_prelude_shadow.vertex.glsl\"\n\nin vec2 a_pos;\n#ifdef ELEVATED_ROADS\nin float a_road_z_offset;\nout highp float v_road_z_offset;\n#endif\n\n#ifdef RENDER_SHADOWS\nuniform mat4 u_light_matrix_0;\nuniform mat4 u_light_matrix_1;\n\nout highp vec4 v_pos_light_view_0;\nout highp vec4 v_pos_light_view_1;\nout highp float v_depth;\n#endif\n\n#ifdef INDICATOR_CUTOUT\nout highp float v_z_offset;\n#endif\n\nuniform mat4 u_matrix;\n\n#pragma mapbox: define highp vec4 color\n#pragma mapbox: define lowp float opacity\n#pragma mapbox: define highp float z_offset\n\nvoid main() {\n    #pragma mapbox: initialize highp vec4 color\n    #pragma mapbox: initialize lowp float opacity\n    #pragma mapbox: initialize highp float z_offset\n\n#ifdef ELEVATED_ROADS\n    z_offset += a_road_z_offset;\n    v_road_z_offset = z_offset;\n#endif\n    float hidden = float(opacity == 0.0);\n    gl_Position = mix(u_matrix * vec4(a_pos, z_offset, 1), AWAY, hidden);\n\n#ifdef RENDER_SHADOWS\n    vec3 shd_pos0 = vec3(a_pos, z_offset);\n    vec3 shd_pos1 = vec3(a_pos, z_offset);\n#ifdef NORMAL_OFFSET\n    vec3 offset = shadow_normal_offset(vec3(0.0, 0.0, 1.0));\n    shd_pos0 += offset * shadow_normal_offset_multiplier0();\n    shd_pos1 += offset * shadow_normal_offset_multiplier1();\n#endif\n    v_pos_light_view_0 = u_light_matrix_0 * vec4(shd_pos0, 1);\n    v_pos_light_view_1 = u_light_matrix_1 * vec4(shd_pos1, 1);\n    v_depth = gl_Position.w;\n#endif\n\n#ifdef FOG\n    v_fog_pos = fog_position(a_pos);\n#endif\n#ifdef INDICATOR_CUTOUT\n    v_z_offset = z_offset;\n#endif\n}\n";

var fillOutlineFrag = "#include \"_prelude_fog.fragment.glsl\"\n#include \"_prelude_lighting.glsl\"\n#include \"_prelude_shadow.fragment.glsl\"\n\nin highp vec2 v_pos;\n\nuniform float u_emissive_strength;\n\n#ifdef RENDER_SHADOWS\nuniform vec3 u_ground_shadow_factor;\n\nin highp vec4 v_pos_light_view_0;\nin highp vec4 v_pos_light_view_1;\nin highp float v_depth;\n#endif\n\n#pragma mapbox: define highp vec4 outline_color\n#pragma mapbox: define lowp float opacity\n\nvoid main() {\n    #pragma mapbox: initialize highp vec4 outline_color\n    #pragma mapbox: initialize lowp float opacity\n\n    float dist = length(v_pos - gl_FragCoord.xy);\n    float alpha = 1.0 - smoothstep(0.0, 1.0, dist);\n    vec4 out_color = outline_color;\n\n#ifdef LIGHTING_3D_MODE\n    out_color = apply_lighting_with_emission_ground(out_color, u_emissive_strength);\n#ifdef RENDER_SHADOWS\n    float light = shadowed_light_factor(v_pos_light_view_0, v_pos_light_view_1, v_depth);\n    out_color.rgb *= mix(u_ground_shadow_factor, vec3(1.0), light);\n#endif // RENDER_SHADOWS\n#endif // LIGHTING_3D_MODE\n\n#ifdef FOG\n    out_color = fog_dither(fog_apply_premultiplied(out_color, v_fog_pos));\n#endif\n\n#ifdef FEATURE_CUTOUT\n    out_color = apply_feature_cutout(out_color, gl_FragCoord);\n#endif\n\n    glFragColor = out_color * (alpha * opacity);\n\n#ifdef OVERDRAW_INSPECTOR\n    glFragColor = vec4(1.0);\n#endif\n    HANDLE_WIREFRAME_DEBUG;\n}\n";

var fillOutlineVert = "#include \"_prelude_fog.vertex.glsl\"\n#include \"_prelude_shadow.vertex.glsl\"\n\nin vec2 a_pos;\n#ifdef ELEVATED_ROADS\nin float a_road_z_offset;\n#endif\n\n#ifdef RENDER_SHADOWS\nuniform mat4 u_light_matrix_0;\nuniform mat4 u_light_matrix_1;\n\nout highp vec4 v_pos_light_view_0;\nout highp vec4 v_pos_light_view_1;\nout highp float v_depth;\n#endif\n\nuniform mat4 u_matrix;\nuniform vec2 u_world;\n\nout highp vec2 v_pos;\n\n#pragma mapbox: define highp vec4 outline_color\n#pragma mapbox: define lowp float opacity\n#pragma mapbox: define highp float z_offset\n\nvoid main() {\n    #pragma mapbox: initialize highp vec4 outline_color\n    #pragma mapbox: initialize lowp float opacity\n    #pragma mapbox: initialize highp float z_offset\n\n#ifdef ELEVATED_ROADS\n    z_offset += a_road_z_offset;\n#endif\n    float hidden = float(opacity == 0.0);\n    gl_Position = mix(u_matrix * vec4(a_pos, z_offset, 1), AWAY, hidden);\n#ifdef FLIP_Y\n    v_pos = (vec2(gl_Position.x, -gl_Position.y) / gl_Position.w + 1.0) / 2.0 * u_world;\n#else\n    v_pos = (gl_Position.xy / gl_Position.w + 1.0) / 2.0 * u_world;\n#endif\n\n#ifdef RENDER_SHADOWS\n    vec3 shd_pos0 = vec3(a_pos, z_offset);\n    vec3 shd_pos1 = vec3(a_pos, z_offset);\n#ifdef NORMAL_OFFSET\n    vec3 offset = shadow_normal_offset(vec3(0.0, 0.0, 1.0));\n    shd_pos0 += offset * shadow_normal_offset_multiplier0();\n    shd_pos1 += offset * shadow_normal_offset_multiplier1();\n#endif\n    v_pos_light_view_0 = u_light_matrix_0 * vec4(shd_pos0, 1);\n    v_pos_light_view_1 = u_light_matrix_1 * vec4(shd_pos1, 1);\n    v_depth = gl_Position.w;\n#endif\n\n#ifdef FOG\n    v_fog_pos = fog_position(a_pos);\n#endif\n}\n";

var fillOutlinePatternFrag = "#include \"_prelude_fog.fragment.glsl\"\n#include \"_prelude_lighting.glsl\"\n#include \"_prelude_shadow.fragment.glsl\"\n\nuniform vec2 u_texsize;\nuniform sampler2D u_image;\n\n#ifdef FILL_PATTERN_TRANSITION\nuniform float u_pattern_transition;\n#endif\n\nuniform float u_emissive_strength;\n\n#ifdef APPLY_LUT_ON_GPU\nuniform highp sampler3D u_lutTexture;\n#endif\n\n#ifdef RENDER_SHADOWS\nuniform vec3 u_ground_shadow_factor;\n\nin highp vec4 v_pos_light_view_0;\nin highp vec4 v_pos_light_view_1;\nin highp float v_depth;\n#endif\n\nin highp vec2 v_pos;\nin highp vec2 v_pos_world;\n\n#pragma mapbox: define lowp float opacity\n#pragma mapbox: define lowp vec4 pattern\n#ifdef FILL_PATTERN_TRANSITION\n#pragma mapbox: define mediump vec4 pattern_b\n#endif\n\nvoid main() {\n    #pragma mapbox: initialize lowp float opacity\n    #pragma mapbox: initialize mediump vec4 pattern\n    #ifdef FILL_PATTERN_TRANSITION\n    #pragma mapbox: initialize mediump vec4 pattern_b\n    #endif\n\n    vec2 pattern_tl = pattern.xy;\n    vec2 pattern_br = pattern.zw;\n\n    highp vec2 imagecoord = mod(v_pos, 1.0);\n    highp vec2 pos = mix(pattern_tl / u_texsize, pattern_br / u_texsize, imagecoord);\n    highp vec2 lod_pos = mix(pattern_tl / u_texsize, pattern_br / u_texsize, v_pos);\n\n    // find distance to outline for alpha interpolation\n\n    float dist = length(v_pos_world - gl_FragCoord.xy);\n    float alpha = 1.0 - smoothstep(0.0, 1.0, dist);\n\n    vec4 out_color = textureLodCustom(u_image, pos, lod_pos);\n\n#ifdef APPLY_LUT_ON_GPU\n    out_color = applyLUT(u_lutTexture, out_color);\n#endif\n\n#ifdef FILL_PATTERN_TRANSITION\n    vec2 pattern_b_tl = pattern_b.xy;\n    vec2 pattern_b_br = pattern_b.zw;\n    highp vec2 pos_b = mix(pattern_b_tl / u_texsize, pattern_b_br / u_texsize, imagecoord);\n    vec4 color_b = textureLodCustom(u_image, pos_b, lod_pos);\n    out_color = out_color * (1.0 - u_pattern_transition) + color_b * u_pattern_transition;\n#endif\n\n#ifdef LIGHTING_3D_MODE\n    out_color = apply_lighting_with_emission_ground(out_color, u_emissive_strength);\n#ifdef RENDER_SHADOWS\n    float light = shadowed_light_factor(v_pos_light_view_0, v_pos_light_view_1, v_depth);\n    out_color.rgb *= mix(u_ground_shadow_factor, vec3(1.0), light);\n#endif // RENDER_SHADOWS\n#endif // LIGHTING_3D_MODE\n\n#ifdef FEATURE_CUTOUT\n    out_color = apply_feature_cutout(out_color, gl_FragCoord);\n#endif\n\n#ifdef FOG\n    out_color = fog_dither(fog_apply_premultiplied(out_color, v_fog_pos));\n#endif\n\n    glFragColor = out_color * (alpha * opacity);\n\n#ifdef OVERDRAW_INSPECTOR\n    glFragColor = vec4(1.0);\n#endif\n\n    HANDLE_WIREFRAME_DEBUG;\n}\n";

var fillOutlinePatternVert = "#include \"_prelude_fog.vertex.glsl\"\n#include \"_prelude_shadow.vertex.glsl\"\n\nuniform mat4 u_matrix;\nuniform vec2 u_world;\nuniform vec2 u_pixel_coord_upper;\nuniform vec2 u_pixel_coord_lower;\nuniform float u_tile_units_to_pixels;\n\nin vec2 a_pos;\n#ifdef ELEVATED_ROADS\nin float a_road_z_offset;\n#endif\n\n#ifdef RENDER_SHADOWS\nuniform mat4 u_light_matrix_0;\nuniform mat4 u_light_matrix_1;\n\nout highp vec4 v_pos_light_view_0;\nout highp vec4 v_pos_light_view_1;\nout highp float v_depth;\n#endif\n\nout highp vec2 v_pos;\nout highp vec2 v_pos_world;\n\n#pragma mapbox: define lowp float opacity\n#pragma mapbox: define lowp vec4 pattern\n#ifdef FILL_PATTERN_TRANSITION\n#pragma mapbox: define mediump vec4 pattern_b\n#endif\n#pragma mapbox: define lowp float pixel_ratio\n#pragma mapbox: define highp float z_offset\n\nvoid main() {\n    #pragma mapbox: initialize lowp float opacity\n    #pragma mapbox: initialize mediump vec4 pattern\n    #ifdef FILL_PATTERN_TRANSITION\n    #pragma mapbox: initialize mediump vec4 pattern_b\n    #endif\n    #pragma mapbox: initialize lowp float pixel_ratio\n    #pragma mapbox: initialize highp float z_offset\n\n    vec2 pattern_tl = pattern.xy;\n    vec2 pattern_br = pattern.zw;\n\n#ifdef ELEVATED_ROADS\n    z_offset += a_road_z_offset;\n#endif\n    float hidden = float(opacity == 0.0);\n    gl_Position = mix(u_matrix * vec4(a_pos, z_offset, 1), AWAY, hidden);\n\n    vec2 display_size = (pattern_br - pattern_tl) / pixel_ratio;\n\n    v_pos = get_pattern_pos(u_pixel_coord_upper, u_pixel_coord_lower, display_size, u_tile_units_to_pixels, a_pos);\n\n#ifdef FLIP_Y\n    v_pos_world = (vec2(gl_Position.x, -gl_Position.y) / gl_Position.w + 1.0) / 2.0 * u_world;\n#else\n    v_pos_world = (gl_Position.xy / gl_Position.w + 1.0) / 2.0 * u_world;\n#endif\n\n#ifdef RENDER_SHADOWS\n    vec3 shd_pos0 = vec3(a_pos, z_offset);\n    vec3 shd_pos1 = vec3(a_pos, z_offset);\n#ifdef NORMAL_OFFSET\n    vec3 offset = shadow_normal_offset(vec3(0.0, 0.0, 1.0));\n    shd_pos0 += offset * shadow_normal_offset_multiplier0();\n    shd_pos1 += offset * shadow_normal_offset_multiplier1();\n#endif\n    v_pos_light_view_0 = u_light_matrix_0 * vec4(shd_pos0, 1);\n    v_pos_light_view_1 = u_light_matrix_1 * vec4(shd_pos1, 1);\n    v_depth = gl_Position.w;\n#endif\n\n#ifdef FOG\n    v_fog_pos = fog_position(a_pos);\n#endif\n}\n";

var fillPatternFrag = "#include \"_prelude_fog.fragment.glsl\"\n#include \"_prelude_lighting.glsl\"\n#include \"_prelude_shadow.fragment.glsl\"\n\nuniform vec2 u_texsize;\n\nuniform sampler2D u_image;\n\n#ifdef FILL_PATTERN_TRANSITION\nuniform float u_pattern_transition;\n#endif\n\nin highp vec2 v_pos;\n\nuniform float u_emissive_strength;\n\n#ifdef RENDER_SHADOWS\nuniform vec3 u_ground_shadow_factor;\n\nin highp vec4 v_pos_light_view_0;\nin highp vec4 v_pos_light_view_1;\nin highp float v_depth;\n#endif\n\n#ifdef ELEVATED_ROADS\nin highp float v_road_z_offset;\n#endif\n\n#ifdef APPLY_LUT_ON_GPU\nuniform highp sampler3D u_lutTexture;\n#endif\n\n#pragma mapbox: define lowp float opacity\n#pragma mapbox: define lowp vec4 pattern\n#ifdef FILL_PATTERN_TRANSITION\n#pragma mapbox: define mediump vec4 pattern_b\n#endif\n\nvoid main() {\n    #pragma mapbox: initialize lowp float opacity\n    #pragma mapbox: initialize mediump vec4 pattern\n    #ifdef FILL_PATTERN_TRANSITION\n    #pragma mapbox: initialize mediump vec4 pattern_b\n    #endif\n\n    vec2 pattern_tl = pattern.xy;\n    vec2 pattern_br = pattern.zw;\n\n    highp vec2 imagecoord = mod(v_pos, 1.0);\n    highp vec2 pos = mix(pattern_tl / u_texsize, pattern_br / u_texsize, imagecoord);\n    highp vec2 lod_pos = mix(pattern_tl / u_texsize, pattern_br / u_texsize, v_pos);\n    vec4 out_color = textureLodCustom(u_image, pos, lod_pos);\n\n#ifdef APPLY_LUT_ON_GPU\n    out_color = applyLUT(u_lutTexture, out_color);\n#endif\n\n#ifdef FILL_PATTERN_TRANSITION\n    vec2 pattern_b_tl = pattern_b.xy;\n    vec2 pattern_b_br = pattern_b.zw;\n    highp vec2 pos_b = mix(pattern_b_tl / u_texsize, pattern_b_br / u_texsize, imagecoord);\n    vec4 color_b = textureLodCustom(u_image, pos_b, lod_pos);\n    out_color = out_color * (1.0 - u_pattern_transition) + color_b * u_pattern_transition;\n#endif\n\n#ifdef LIGHTING_3D_MODE\n    out_color = apply_lighting_with_emission_ground(out_color, u_emissive_strength);\n#ifdef RENDER_SHADOWS\n    float light = shadowed_light_factor(v_pos_light_view_0, v_pos_light_view_1, v_depth);\n#ifdef ELEVATED_ROADS\n    out_color.rgb *= mix(v_road_z_offset != 0.0 ? u_ground_shadow_factor : vec3(1.0), vec3(1.0), light);\n#else\n    out_color.rgb *= mix(u_ground_shadow_factor, vec3(1.0), light);\n#endif\n#endif // RENDER_SHADOWS\n#endif // LIGHTING_3D_MODE\n\n#ifdef FEATURE_CUTOUT\n    out_color = apply_feature_cutout(out_color, gl_FragCoord);\n#endif\n\n#ifdef FOG\n    out_color = fog_dither(fog_apply_premultiplied(out_color, v_fog_pos));\n#endif\n\n    glFragColor = out_color * opacity;\n\n#ifdef OVERDRAW_INSPECTOR\n    glFragColor = vec4(1.0);\n#endif\n\n    HANDLE_WIREFRAME_DEBUG;\n}\n";

var fillPatternVert = "#include \"_prelude_fog.vertex.glsl\"\n#include \"_prelude_shadow.vertex.glsl\"\n\nuniform mat4 u_matrix;\nuniform vec2 u_pixel_coord_upper;\nuniform vec2 u_pixel_coord_lower;\nuniform float u_tile_units_to_pixels;\n\nin vec2 a_pos;\n#ifdef ELEVATED_ROADS\nin float a_road_z_offset;\nout highp float v_road_z_offset;\n#endif\n\n#ifdef RENDER_SHADOWS\nuniform mat4 u_light_matrix_0;\nuniform mat4 u_light_matrix_1;\n\nout highp vec4 v_pos_light_view_0;\nout highp vec4 v_pos_light_view_1;\nout highp float v_depth;\n#endif\n\nout highp vec2 v_pos;\n\n#pragma mapbox: define lowp float opacity\n#pragma mapbox: define lowp vec4 pattern\n#ifdef FILL_PATTERN_TRANSITION\n#pragma mapbox: define mediump vec4 pattern_b\n#endif\n#pragma mapbox: define lowp float pixel_ratio\n#pragma mapbox: define highp float z_offset\n\nvoid main() {\n    #pragma mapbox: initialize lowp float opacity\n    #pragma mapbox: initialize mediump vec4 pattern\n    #pragma mapbox: initialize lowp float pixel_ratio\n    #pragma mapbox: initialize highp float z_offset\n    #ifdef FILL_PATTERN_TRANSITION\n    #pragma mapbox: initialize mediump vec4 pattern_b\n    #endif\n\n    vec2 pattern_tl = pattern.xy;\n    vec2 pattern_br = pattern.zw;\n\n    vec2 display_size = (pattern_br - pattern_tl) / pixel_ratio;\n#ifdef ELEVATED_ROADS\n    z_offset += a_road_z_offset;\n    v_road_z_offset = z_offset;\n#endif\n    float hidden = float(opacity == 0.0);\n    gl_Position = mix(u_matrix * vec4(a_pos, z_offset, 1), AWAY, hidden);\n    v_pos = get_pattern_pos(u_pixel_coord_upper, u_pixel_coord_lower, display_size, u_tile_units_to_pixels, a_pos);\n\n#ifdef RENDER_SHADOWS\n    vec3 shd_pos0 = vec3(a_pos, z_offset);\n    vec3 shd_pos1 = vec3(a_pos, z_offset);\n#ifdef NORMAL_OFFSET\n    vec3 offset = shadow_normal_offset(vec3(0.0, 0.0, 1.0));\n    shd_pos0 += offset * shadow_normal_offset_multiplier0();\n    shd_pos1 += offset * shadow_normal_offset_multiplier1();\n#endif\n    v_pos_light_view_0 = u_light_matrix_0 * vec4(shd_pos0, 1);\n    v_pos_light_view_1 = u_light_matrix_1 * vec4(shd_pos1, 1);\n    v_depth = gl_Position.w;\n#endif\n\n#ifdef FOG\n    v_fog_pos = fog_position(a_pos);\n#endif\n}\n";

var fillExtrusionFrag = "#include \"_prelude_fog.fragment.glsl\"\n#include \"_prelude_shadow.fragment.glsl\"\n#include \"_prelude_lighting.glsl\"\n\nin vec4 v_color;\nin vec4 v_flat;\n\n#ifdef RENDER_SHADOWS\nin highp vec4 v_pos_light_view_0;\nin highp vec4 v_pos_light_view_1;\n#endif\n\nuniform lowp float u_opacity;\n\n#ifdef FAUX_AO\nuniform lowp vec2 u_ao;\nin vec2 v_ao;\n#endif\n\n#if defined(ZERO_ROOF_RADIUS) && !defined(LIGHTING_3D_MODE)\nin vec4 v_roof_color;\n#endif\n\n#if defined(ZERO_ROOF_RADIUS) || defined(RENDER_SHADOWS) || defined(LIGHTING_3D_MODE)\nin highp vec3 v_normal;\n#endif\n\nuniform vec3 u_flood_light_color;\nuniform highp float u_vertical_scale;\nuniform float u_flood_light_intensity;\nuniform vec3 u_ground_shadow_factor;\n\n#if defined(LIGHTING_3D_MODE) && defined(FLOOD_LIGHT)\nin float v_flood_radius;\nin float v_has_floodlight;\n#endif\n\nin float v_height;\n\n#pragma mapbox: define highp float emissive_strength\n\nvoid main() {\n    #pragma mapbox: initialize highp float emissive_strength\n\n#if defined(ZERO_ROOF_RADIUS) || defined(RENDER_SHADOWS) || defined(LIGHTING_3D_MODE)\n    vec3 normal = normalize(v_normal);\n#endif\n\nfloat z;\nvec4 color = v_color;\n#ifdef ZERO_ROOF_RADIUS\n    z = float(normal.z > 0.00001);\n#ifdef LIGHTING_3D_MODE\n    normal = mix(normal, vec3(0.0, 0.0, 1.0), z);\n#else // LIGHTING_3D_MODE\n    color = mix(v_color, v_roof_color, z);\n#endif // !LIGHTING_3D_MODE\n#endif // ZERO_ROOF_RADIUS\n\nfloat h = max(0.0, v_height);\nfloat ao_shade = 1.0;\n#ifdef FAUX_AO\n    float intensity = u_ao[0];\n    float h_floors = h / (u_ao[1] * u_vertical_scale);\n    float y_shade = 1.0 - 0.9 * intensity * min(v_ao.y, 1.0);\n    ao_shade = (1.0 - 0.08 * intensity) * (y_shade + (1.0 - y_shade) * (1.0 - pow(1.0 - min(h_floors / 16.0, 1.0), 16.0))) + 0.08 * intensity * min(h_floors / 160.0, 1.0);\n    // concave angle\n    float concave = v_ao.x * v_ao.x;\n#ifdef ZERO_ROOF_RADIUS\n    concave *= (1.0 - z);\n#endif\n    float x_shade = mix(1.0, mix(0.6, 0.75, min(h_floors / 30.0, 1.0)), intensity) + 0.1 * intensity * min(h, 1.0);\n    ao_shade *= mix(1.0, x_shade * x_shade * x_shade, concave);\n\n#ifdef LIGHTING_3D_MODE\n#ifdef FLOOD_LIGHT\n    color.rgb *= mix(ao_shade, 1.0, v_has_floodlight); // flood light and AO are mutually exclusive effects.\n#else // FLOOD_LIGHT\n    color.rgb *= ao_shade;\n#endif // !FLOOD_LIGHT\n#else // LIGHTING_3D_MODE\n    color.rgb *= ao_shade;\n#endif // !LIGHTING_3D_MODE\n\n#endif // FAUX_AO\n\n#ifdef LIGHTING_3D_MODE\n\nfloat flood_radiance = 0.0;\n#ifdef FLOOD_LIGHT\n    flood_radiance = (1.0 - min(h / v_flood_radius, 1.0)) * u_flood_light_intensity * v_has_floodlight;\n#endif // FLOOD_LIGHT\n#ifdef RENDER_SHADOWS\n#ifdef FLOOD_LIGHT\n    float ndotl_unclamped = dot(normal, u_shadow_direction);\n    float ndotl = max(0.0, ndotl_unclamped);\n    float occlusion = ndotl_unclamped < 0.0 ? 1.0 : shadow_occlusion(ndotl, v_pos_light_view_0, v_pos_light_view_1, 1.0 / gl_FragCoord.w);\n\n    // Compute both FE and flood lights separately and interpolate between the two.\n    // \"litColor\" uses pretty much \"shadowed_light_factor_normal\" as the directional component.\n    vec3 litColor = apply_lighting(color.rgb, normal, (1.0 - u_shadow_intensity * occlusion) * ndotl);\n    vec3 floodLitColor = compute_flood_lighting(u_flood_light_color * u_opacity, 1.0 - u_shadow_intensity, occlusion, u_ground_shadow_factor);\n\n    color.rgb = mix(litColor, floodLitColor, flood_radiance);\n#else // FLOOD_LIGHT\n    float shadowed_lighting_factor;\n#ifdef RENDER_CUTOFF\n    shadowed_lighting_factor = shadowed_light_factor_normal_opacity(normal, v_pos_light_view_0, v_pos_light_view_1, 1.0 / gl_FragCoord.w, v_cutoff_opacity);\n    if (v_cutoff_opacity == 0.0) {\n        discard;\n    }\n#else // RENDER_CUTOFF\n    shadowed_lighting_factor = shadowed_light_factor_normal(normal, v_pos_light_view_0, v_pos_light_view_1, 1.0 / gl_FragCoord.w);\n#endif // RENDER_CUTOFF\n    color.rgb = apply_lighting(color.rgb, normal, shadowed_lighting_factor);\n#endif // !FLOOD_LIGHT \n#else // RENDER_SHADOWS\n    color.rgb = apply_lighting(color.rgb, normal);\n#ifdef FLOOD_LIGHT\n    color.rgb = mix(color.rgb, u_flood_light_color * u_opacity, flood_radiance);\n#endif // FLOOD_LIGHT\n#endif // !RENDER_SHADOWS\n\n    color.rgb = mix(color.rgb, v_flat.rgb, emissive_strength);\n    color *= u_opacity;\n#endif // LIGHTING_3D_MODE\n\n#ifdef FOG\n    color = fog_dither(fog_apply_premultiplied(color, v_fog_pos, h));\n#endif\n\n#ifdef INDICATOR_CUTOUT\n    color = applyCutout(color, h);\n#endif\n\n#ifdef FEATURE_CUTOUT\n    color = apply_feature_cutout(color, gl_FragCoord);\n#endif\n\n    glFragColor = color;\n\n#ifdef OVERDRAW_INSPECTOR\n    glFragColor = vec4(1.0);\n#endif\n\n    HANDLE_WIREFRAME_DEBUG;\n}\n";

var fillExtrusionVert = "#include \"_prelude_fog.vertex.glsl\"\n#include \"_prelude_terrain.vertex.glsl\"\n#include \"_prelude_shadow.vertex.glsl\"\n#include \"_prelude_lighting.glsl\"\n\nuniform mat4 u_matrix;\nuniform vec3 u_lightcolor;\nuniform lowp vec3 u_lightpos;\nuniform lowp float u_lightintensity;\nuniform float u_vertical_gradient;\nuniform lowp float u_opacity;\nuniform float u_edge_radius;\nuniform float u_width_scale;\n\nin vec4 a_pos_normal_ed;\nin vec2 a_centroid_pos;\n\n#ifdef RENDER_WALL_MODE\nin vec3 a_join_normal_inside;\n#endif\n\n#ifdef PROJECTION_GLOBE_VIEW\nin vec3 a_pos_3;         // Projected position on the globe\nin vec3 a_pos_normal_3;  // Surface normal at the position\n\nuniform mat4 u_inv_rot_matrix;\nuniform vec2 u_merc_center;\nuniform vec3 u_tile_id;\nuniform float u_zoom_transition;\nuniform vec3 u_up_dir;\nuniform float u_height_lift;\n#endif\n\n#ifdef TERRAIN\nuniform int u_height_type;\nuniform int u_base_type;\n#endif\n\nuniform highp float u_vertical_scale;\n\nout vec4 v_color;\nout vec4 v_flat;\n\n#ifdef RENDER_SHADOWS\nuniform mat4 u_light_matrix_0;\nuniform mat4 u_light_matrix_1;\n\nout highp vec4 v_pos_light_view_0;\nout highp vec4 v_pos_light_view_1;\n\n#endif\n\n#if defined(ZERO_ROOF_RADIUS) && !defined(LIGHTING_3D_MODE)\nout vec4 v_roof_color;\n#endif\n\n#if defined(ZERO_ROOF_RADIUS) || defined(RENDER_SHADOWS) || defined(LIGHTING_3D_MODE)\nout highp vec3 v_normal;\n#endif\n\n#ifdef FAUX_AO\nuniform lowp vec2 u_ao;\nout vec2 v_ao;\n#endif\n\n#if defined(LIGHTING_3D_MODE) && defined(FLOOD_LIGHT)\nout float v_flood_radius;\nout float v_has_floodlight;\n#endif\n\nout float v_height;\n\n// linear to sRGB approximation\nvec3 linearTosRGB(vec3 color) {\n    return pow(color, vec3(1./2.2));\n}\nvec3 sRGBToLinear(vec3 srgbIn) {\n    return pow(srgbIn, vec3(2.2));\n}\n\n#pragma mapbox: define highp float base\n#pragma mapbox: define highp float height\n\n#pragma mapbox: define highp vec4 color\n#pragma mapbox: define highp float flood_light_wall_radius\n#pragma mapbox: define highp float line_width\n#pragma mapbox: define highp float emissive_strength\n\nvoid main() {\n    #pragma mapbox: initialize highp float base\n    #pragma mapbox: initialize highp float height\n    #pragma mapbox: initialize highp vec4 color\n    #pragma mapbox: initialize highp float flood_light_wall_radius\n    #pragma mapbox: initialize highp float line_width\n    #pragma mapbox: initialize highp float emissive_strength\n    \n    base *= u_vertical_scale;\n    height *= u_vertical_scale;\n    \n    vec4 pos_nx = floor(a_pos_normal_ed * 0.5);\n    // The least significant bits of a_pos_normal_ed hold:\n    // x is 1 if it's on top, 0 for ground.\n    // y is 1 if the normal points up, and 0 if it points to side.\n    // z is sign of ny: 1 for positive, 0 for values <= 0.\n    // w marks edge's start, 0 is for edge end, edgeDistance increases from start to end.\n    vec4 top_up_ny_start = a_pos_normal_ed - 2.0 * pos_nx;\n    vec3 top_up_ny = top_up_ny_start.xyz;\n\n    float x_normal = pos_nx.z / 8192.0;\n    vec3 normal = top_up_ny.y == 1.0 ? vec3(0.0, 0.0, 1.0) : normalize(vec3(x_normal, (2.0 * top_up_ny.z - 1.0) * (1.0 - abs(x_normal)), 0.0));\n#if defined(ZERO_ROOF_RADIUS) || defined(RENDER_SHADOWS) || defined(LIGHTING_3D_MODE)\n    v_normal = normal;\n#endif\n\n    base = max(0.0, base);\n\n    float attr_height = height;\n    height = max(0.0, top_up_ny.y == 0.0 && top_up_ny.x == 1.0 ? height - u_edge_radius : height);\n\n    float t = top_up_ny.x;\n\n    vec2 centroid_pos = vec2(0.0);\n#if defined(HAS_CENTROID) || defined(TERRAIN)\n    centroid_pos = a_centroid_pos;\n#endif\n\n    float ele = 0.0;\n    float h = 0.0;\n    float c_ele = 0.0;\n    vec3 pos;\n#ifdef TERRAIN\n    bool is_flat_height = centroid_pos.x != 0.0 && u_height_type == 1;\n    bool is_flat_base = centroid_pos.x != 0.0 && u_base_type == 1;\n    ele = elevation(pos_nx.xy);\n    c_ele = is_flat_height || is_flat_base ? (centroid_pos.y == 0.0 ? elevationFromUint16(centroid_pos.x) : flatElevation(centroid_pos)) : ele;\n    float h_height = is_flat_height ? max(c_ele + height, ele + base + 2.0) : ele + height;\n    float h_base = is_flat_base ? max(c_ele + base, ele + base) : ele + (base == 0.0 ? -5.0 : base);\n    h = t > 0.0 ? max(h_base, h_height) : h_base;\n    pos = vec3(pos_nx.xy, h);\n#else\n    h = t > 0.0 ? height : base;\n    pos = vec3(pos_nx.xy, h);\n#endif\n\n#ifdef PROJECTION_GLOBE_VIEW\n    // If t > 0 (top) we always add the lift, otherwise (ground) we only add it if base height is > 0\n    float lift = float((t + base) > 0.0) * u_height_lift;\n    h += lift;\n    vec3 globe_normal = normalize(mix(a_pos_normal_3 / 16384.0, u_up_dir, u_zoom_transition));\n    vec3 globe_pos = a_pos_3 + globe_normal * (u_tile_up_scale * h);\n    vec3 merc_pos = mercator_tile_position(u_inv_rot_matrix, pos.xy, u_tile_id, u_merc_center) + u_up_dir * u_tile_up_scale * pos.z;\n    pos = mix_globe_mercator(globe_pos, merc_pos, u_zoom_transition);\n#endif\n\n    float cutoff = 1.0;\n    vec3 scaled_pos = pos;\n#ifdef RENDER_CUTOFF\n    vec3 centroid_random = vec3(centroid_pos.xy, centroid_pos.x + centroid_pos.y + 1.0);\n    vec3 ground_pos = centroid_pos.x == 0.0 ? pos.xyz : (centroid_random / 8.0);\n    vec4 ground = u_matrix * vec4(ground_pos.xy, ele, 1.0);\n#ifdef CLIP_ZERO_TO_ONE\n    cutoff = cutoff_opacity(u_cutoff_params, ground.z * 2.0 - ground.w);\n#else\n    cutoff = cutoff_opacity(u_cutoff_params, ground.z);\n#endif\n    if (centroid_pos.y != 0.0 && centroid_pos.x != 0.0) {\n        vec3 g = floor(ground_pos);\n        vec3 mod_ = centroid_random - g * 8.0;\n        float seed = min(1.0, 0.1 * (min(3.5, max(mod_.x + mod_.y, 0.2 * attr_height)) * 0.35 + mod_.z));\n        if (cutoff < 0.8 - seed) {\n            cutoff = 0.0;\n        }\n    }\n    float cutoff_scale = cutoff;\n    v_cutoff_opacity = cutoff;\n\n    scaled_pos.z = mix(c_ele, h, cutoff_scale);\n#endif\n    float hidden = float((centroid_pos.x == 0.0 && centroid_pos.y == 1.0) || (cutoff == 0.0 && centroid_pos.x != 0.0) || (color.a == 0.0));\n\n#ifdef RENDER_WALL_MODE\n    vec2 wall_offset = u_width_scale * line_width * (a_join_normal_inside.xy / EXTENT);\n    scaled_pos.xy += (1.0 - a_join_normal_inside.z) * wall_offset * 0.5;\n    scaled_pos.xy -= a_join_normal_inside.z * wall_offset * 0.5;\n#endif\n    gl_Position = mix(u_matrix * vec4(scaled_pos, 1), AWAY, hidden);\n    h = h - ele;\n    v_height = h;\n\n#ifdef RENDER_SHADOWS\n    vec3 shd_pos0 = pos;\n    vec3 shd_pos1 = pos;\n#ifdef NORMAL_OFFSET\n    vec3 offset = shadow_normal_offset(normal);\n    shd_pos0 += offset * shadow_normal_offset_multiplier0();\n    shd_pos1 += offset * shadow_normal_offset_multiplier1();\n#endif\n    v_pos_light_view_0 = u_light_matrix_0 * vec4(shd_pos0, 1);\n    v_pos_light_view_1 = u_light_matrix_1 * vec4(shd_pos1, 1);\n#endif\n\n    float NdotL = 0.0;\n    float colorvalue = 0.0;\n#ifndef LIGHTING_3D_MODE\n    // Relative luminance (how dark/bright is the surface color?)\n    colorvalue = color.r * 0.2126 + color.g * 0.7152 + color.b * 0.0722;\n\n    // Add slight ambient lighting so no extrusions are totally black\n    vec4 ambientlight = vec4(0.03, 0.03, 0.03, 1.0);\n    color += ambientlight;\n\n    // Calculate cos(theta), where theta is the angle between surface normal and diffuse light ray\n    NdotL = clamp(dot(normal, u_lightpos), 0.0, 1.0);\n\n    // Adjust NdotL so that\n    // the range of values for highlight/shading is narrower\n    // with lower light intensity\n    // and with lighter/brighter surface colors\n    NdotL = mix((1.0 - u_lightintensity), max((1.0 - colorvalue + u_lightintensity), 1.0), NdotL);\n\n    // Add gradient along z axis of side surfaces\n    if (normal.y != 0.0) {\n        float r = 0.84;\n        r = mix(0.7, 0.98, 1.0 - u_lightintensity);\n        // This avoids another branching statement, but multiplies by a constant of 0.84 if no vertical gradient,\n        // and otherwise calculates the gradient based on base + height\n        NdotL *= (\n            (1.0 - u_vertical_gradient) +\n            (u_vertical_gradient * clamp((t + base) * pow(height / 150.0, 0.5), r, 1.0)));\n    }\n#endif // !LIGHTING_3D_MODE\n\n#ifdef FAUX_AO\n    // Documented at https://github.com/mapbox/mapbox-gl-js/pull/11926#discussion_r898496259\n    float concave = pos_nx.w - floor(pos_nx.w * 0.5) * 2.0;\n    float start = top_up_ny_start.w;\n    float y_ground = 1.0 - clamp(t + base, 0.0, 1.0);\n    float top_height = height;\n#ifdef TERRAIN\n    top_height = mix(max(c_ele + height, ele + base + 2.0), ele + height, float(centroid_pos.x == 0.0)) - ele;\n    y_ground += y_ground * 5.0 / max(3.0, top_height);\n#endif // TERRAIN\n    v_ao = vec2(mix(concave, -concave, start), y_ground);\n    NdotL *= (1.0 + 0.05 * (1.0 - top_up_ny.y) * u_ao[0]); // compensate sides faux ao shading contribution\n\n#ifdef PROJECTION_GLOBE_VIEW\n    top_height += u_height_lift;\n#endif // PROJECTION_GLOBE_VIEW\n    gl_Position.z -= (0.0000006 * (min(top_height, 500.) + 2.0 * min(base, 500.0) + 60.0 * concave + 3.0 * start)) * gl_Position.w;\n#endif // FAUX_AO\n\n#ifdef LIGHTING_3D_MODE\n\n#ifdef FLOOD_LIGHT\n    float is_wall = 1.0 - float(t > 0.0 && top_up_ny.y > 0.0);\n    v_has_floodlight = float(flood_light_wall_radius > 0.0 && is_wall > 0.0);\n    v_flood_radius = flood_light_wall_radius * u_vertical_scale;\n#endif // FLOOD_LIGHT\n\n    v_color = vec4(color.rgb, 1.0);\n    float ndotl = calculate_NdotL(normal);\n    v_flat.rgb = sRGBToLinear(color.rgb);\n    v_flat.rgb = v_flat.rgb * (ndotl + (1.0 - min(ndotl * 57.29, 1.0)) * emissive_strength);\n    v_flat = vec4(linearTosRGB(v_flat.rgb), 1.0);\n#else // LIGHTING_3D_MODE\n    // Assign final color based on surface + ambient light color, diffuse light NdotL, and light color\n    // with lower bounds adjusted to hue of light\n    // so that shading is tinted with the complementary (opposite) color to the light color\n    v_color = vec4(0.0, 0.0, 0.0, 1.0);\n    v_color.rgb += clamp(color.rgb * NdotL * u_lightcolor, mix(vec3(0.0), vec3(0.3), 1.0 - u_lightcolor), vec3(1.0));\n    v_color *= u_opacity;\n#endif // !LIGHTING_3D_MODE\n\n#if defined(ZERO_ROOF_RADIUS) && !defined(LIGHTING_3D_MODE)\n    float roofNdotL = clamp(u_lightpos.z, 0.0, 1.0);\n    roofNdotL = mix((1.0 - u_lightintensity), max((1.0 - colorvalue + u_lightintensity), 1.0), roofNdotL);\n    v_roof_color = vec4(0.0, 0.0, 0.0, 1.0);\n    v_roof_color.rgb += clamp(color.rgb * roofNdotL * u_lightcolor, mix(vec3(0.0), vec3(0.3), 1.0 - u_lightcolor), vec3(1.0));\n    v_roof_color *= u_opacity;\n#endif // defined(ZERO_ROOF_RADIUS) && !defined(LIGHTING_3D_MODE)\n\n#ifdef FOG\n    v_fog_pos = fog_position(pos);\n#endif\n}\n";

var fillExtrusionPatternFrag = "#include \"_prelude_fog.fragment.glsl\"\n#include \"_prelude_lighting.glsl\"\n\nuniform vec2 u_texsize;\n\nuniform sampler2D u_image;\n\n#ifdef FILL_EXTRUSION_PATTERN_TRANSITION\nuniform float u_pattern_transition;\n#endif\n\n#ifdef FAUX_AO\nuniform lowp vec2 u_ao;\nin vec3 v_ao;\n#endif\n\n#ifdef LIGHTING_3D_MODE\nin vec3 v_normal;\n#endif\n\n#ifdef APPLY_LUT_ON_GPU\nuniform highp sampler3D u_lutTexture;\n#endif\n\nin highp vec2 v_pos;\nin vec4 v_lighting;\n\nuniform lowp float u_opacity;\n\n#pragma mapbox: define highp float base\n#pragma mapbox: define highp float height\n#pragma mapbox: define mediump vec4 pattern\n#ifdef FILL_EXTRUSION_PATTERN_TRANSITION\n#pragma mapbox: define mediump vec4 pattern_b\n#endif\n#pragma mapbox: define highp float pixel_ratio\n\nvoid main() {\n    #pragma mapbox: initialize highp float base\n    #pragma mapbox: initialize highp float height\n    #pragma mapbox: initialize mediump vec4 pattern\n    #ifdef FILL_EXTRUSION_PATTERN_TRANSITION\n    #pragma mapbox: initialize mediump vec4 pattern_b\n    #endif\n    #pragma mapbox: initialize highp float pixel_ratio\n\n    vec2 pattern_tl = pattern.xy;\n    vec2 pattern_br = pattern.zw;\n\n    highp vec2 imagecoord = mod(v_pos, 1.0);\n    highp vec2 pos = mix(pattern_tl / u_texsize, pattern_br / u_texsize, imagecoord);\n    highp vec2 lod_pos = mix(pattern_tl / u_texsize, pattern_br / u_texsize, v_pos);\n    vec4 out_color = textureLodCustom(u_image, pos, lod_pos);\n\n#ifdef APPLY_LUT_ON_GPU\n    out_color = applyLUT(u_lutTexture, out_color);\n#endif\n\n#ifdef FILL_EXTRUSION_PATTERN_TRANSITION\n    vec2 pattern_b_tl = pattern_b.xy;\n    vec2 pattern_b_br = pattern_b.zw;\n    highp vec2 pos_b = mix(pattern_b_tl / u_texsize, pattern_b_br / u_texsize, imagecoord);\n    vec4 color_b = textureLodCustom(u_image, pos_b, lod_pos);\n    out_color = out_color * (1.0 - u_pattern_transition) + color_b * u_pattern_transition;\n#endif\n\n#ifdef LIGHTING_3D_MODE\n    out_color = apply_lighting(out_color, normalize(v_normal)) * u_opacity;\n#else\n    out_color = out_color * v_lighting;\n#endif\n\n#ifdef FAUX_AO\n    float intensity = u_ao[0];\n    float h = max(0.0, v_ao.z);\n    float h_floors = h / u_ao[1];\n    float y_shade = 1.0 - 0.9 * intensity * min(v_ao.y, 1.0);\n    float shade = (1.0 - 0.08 * intensity) * (y_shade + (1.0 - y_shade) * (1.0 - pow(1.0 - min(h_floors / 16.0, 1.0), 16.0))) + 0.08 * intensity * min(h_floors / 160.0, 1.0);\n    // concave angle\n    float concave = v_ao.x * v_ao.x;\n    float x_shade = mix(1.0, mix(0.6, 0.75, min(h_floors / 30.0, 1.0)), intensity) + 0.1 * intensity * min(h, 1.0);\n    shade *= mix(1.0, x_shade * x_shade * x_shade, concave);\n    out_color.rgb = out_color.rgb * shade;\n#endif\n#ifdef FOG\n    out_color = fog_dither(fog_apply_premultiplied(out_color, v_fog_pos));\n#endif\n\n#ifdef INDICATOR_CUTOUT\n    // TODO: maybe use height from vertex shader?\n    out_color = applyCutout(out_color, height);\n#endif\n\n    glFragColor = out_color;\n\n#ifdef OVERDRAW_INSPECTOR\n    glFragColor = vec4(1.0);\n#endif\n\n    HANDLE_WIREFRAME_DEBUG;\n}\n";

var fillExtrusionPatternVert = "#include \"_prelude_fog.vertex.glsl\"\n#include \"_prelude_terrain.vertex.glsl\"\n#include \"_prelude_lighting.glsl\"\n\nuniform mat4 u_matrix;\nuniform vec2 u_pixel_coord_upper;\nuniform vec2 u_pixel_coord_lower;\nuniform float u_height_factor;\nuniform float u_tile_units_to_pixels;\nuniform float u_vertical_gradient;\nuniform lowp float u_opacity;\nuniform float u_width_scale;\n\nuniform vec3 u_lightcolor;\nuniform lowp vec3 u_lightpos;\nuniform lowp float u_lightintensity;\n\nin vec4 a_pos_normal_ed;\nin vec2 a_centroid_pos;\n\n#ifdef RENDER_WALL_MODE\nin vec3 a_join_normal_inside;\n#endif\n\n#ifdef PROJECTION_GLOBE_VIEW\nin vec3 a_pos_3;         // Projected position on the globe\nin vec3 a_pos_normal_3;  // Surface normal at the position\n\nuniform mat4 u_inv_rot_matrix;\nuniform vec2 u_merc_center;\nuniform vec3 u_tile_id;\nuniform float u_zoom_transition;\nuniform vec3 u_up_dir;\nuniform float u_height_lift;\n#endif\n\n#ifdef TERRAIN\nuniform int u_height_type;\nuniform int u_base_type;\n#endif\n\nout highp vec2 v_pos;\nout vec4 v_lighting;\n\n#ifdef FAUX_AO\nuniform lowp vec2 u_ao;\nout vec3 v_ao;\n#endif\n\n#ifdef LIGHTING_3D_MODE\nout vec3 v_normal;\n#endif\n\n#pragma mapbox: define highp float base\n#pragma mapbox: define highp float height\n#pragma mapbox: define highp vec4 color\n#pragma mapbox: define mediump vec4 pattern\n#ifdef FILL_EXTRUSION_PATTERN_TRANSITION\n#pragma mapbox: define mediump vec4 pattern_b\n#endif\n#pragma mapbox: define highp float pixel_ratio\n#pragma mapbox: define highp float line_width\n\nvoid main() {\n    #pragma mapbox: initialize highp float base\n    #pragma mapbox: initialize highp float height\n    #pragma mapbox: initialize highp vec4 color\n    #pragma mapbox: initialize mediump vec4 pattern\n    #ifdef FILL_EXTRUSION_PATTERN_TRANSITION\n    #pragma mapbox: initialize mediump vec4 pattern_b\n    #endif\n    #pragma mapbox: initialize highp float pixel_ratio\n    #pragma mapbox: initialize highp float line_width\n\n    vec2 pattern_tl = pattern.xy;\n    vec2 pattern_br = pattern.zw;\n\n    vec4 pos_nx = floor(a_pos_normal_ed * 0.5);\n    // The least significant bits of a_pos_normal_ed.xy hold:\n    // x is 1 if it's on top, 0 for ground.\n    // y is 1 if the normal points up, and 0 if it points to side.\n    // z is sign of ny: 1 for positive, 0 for values <= 0.\n    // w marks edge's start, 0 is for edge end, edgeDistance increases from start to end.\n    mediump vec4 top_up_ny_start = a_pos_normal_ed - 2.0 * pos_nx;\n    mediump vec3 top_up_ny = top_up_ny_start.xyz;\n\n    float x_normal = pos_nx.z / 8192.0;\n    vec3 normal = top_up_ny.y == 1.0 ? vec3(0.0, 0.0, 1.0) : normalize(vec3(x_normal, (2.0 * top_up_ny.z - 1.0) * (1.0 - abs(x_normal)), 0.0));\n    float edgedistance = a_pos_normal_ed.w;\n\n    vec2 display_size = (pattern_br - pattern_tl) / pixel_ratio;\n\n    base = max(0.0, base);\n    height = max(0.0, height);\n\n    float t = top_up_ny.x;\n    float z = t > 0.0 ? height : base;\n\n    vec2 centroid_pos = vec2(0.0);\n#if defined(HAS_CENTROID) || defined(TERRAIN)\n    centroid_pos = a_centroid_pos;\n#endif\n\n    float ele = 0.0;\n    float h = z;\n    vec3 p;\n    float c_ele;\n#ifdef TERRAIN\n    bool is_flat_height = centroid_pos.x != 0.0 && u_height_type == 1;\n    bool is_flat_base = centroid_pos.x != 0.0 && u_base_type == 1;\n    ele = elevation(pos_nx.xy);\n    c_ele = is_flat_height || is_flat_base ? (centroid_pos.y == 0.0 ? elevationFromUint16(centroid_pos.x) : flatElevation(centroid_pos)) : ele;\n    float h_height = is_flat_height ? max(c_ele + height, ele + base + 2.0) : ele + height;\n    float h_base = is_flat_base ? max(c_ele + base, ele + base) : ele + (base == 0.0 ? -5.0 : base);\n    h = t > 0.0 ? max(h_base, h_height) : h_base;\n    p = vec3(pos_nx.xy, h);\n#else\n    p = vec3(pos_nx.xy, z);\n#endif\n\n#ifdef PROJECTION_GLOBE_VIEW\n    // If t > 0 (top) we always add the lift, otherwise (ground) we only add it if base height is > 0\n    float lift = float((t + base) > 0.0) * u_height_lift;\n    h += lift;\n    vec3 globe_normal = normalize(mix(a_pos_normal_3 / 16384.0, u_up_dir, u_zoom_transition));\n    vec3 globe_pos = a_pos_3 + globe_normal * (u_tile_up_scale * (p.z + lift));\n    vec3 merc_pos = mercator_tile_position(u_inv_rot_matrix, p.xy, u_tile_id, u_merc_center) + u_up_dir * u_tile_up_scale * p.z;\n    p = mix_globe_mercator(globe_pos, merc_pos, u_zoom_transition);\n#endif\n\n#ifdef RENDER_WALL_MODE\n    vec2 wall_offset = u_width_scale * line_width * (a_join_normal_inside.xy / EXTENT);\n    p.xy += (1.0 - a_join_normal_inside.z) * wall_offset * 0.5;\n    p.xy -= a_join_normal_inside.z * wall_offset * 0.5;\n#endif\n    float hidden = float((centroid_pos.x == 0.0 && centroid_pos.y == 1.0) || (color.a == 0.0));\n    gl_Position = mix(u_matrix * vec4(p, 1), AWAY, hidden);\n\n    vec2 pos = normal.z == 1.0\n        ? pos_nx.xy // extrusion top\n        : vec2(edgedistance, z * u_height_factor); // extrusion side\n\n    v_pos = get_pattern_pos(u_pixel_coord_upper, u_pixel_coord_lower, display_size, u_tile_units_to_pixels, pos);\n\n    v_lighting = vec4(0.0, 0.0, 0.0, 1.0);\n    float NdotL = 0.0;\n#ifdef LIGHTING_3D_MODE\n    NdotL = calculate_NdotL(normal);\n#else\n    NdotL = clamp(dot(normal, u_lightpos), 0.0, 1.0);\n    NdotL = mix((1.0 - u_lightintensity), max((0.5 + u_lightintensity), 1.0), NdotL);\n#endif\n\n    if (normal.y != 0.0) {\n        float r = 0.84;\n#ifndef LIGHTING_3D_MODE\n        r = mix(0.7, 0.98, 1.0 - u_lightintensity);\n#endif\n        // This avoids another branching statement, but multiplies by a constant of 0.84 if no vertical gradient,\n        // and otherwise calculates the gradient based on base + height\n        NdotL *= (\n            (1.0 - u_vertical_gradient) +\n            (u_vertical_gradient * clamp((t + base) * pow(height / 150.0, 0.5), r, 1.0)));\n    }\n\n#ifdef FAUX_AO\n    // Documented at https://github.com/mapbox/mapbox-gl-js/pull/11926#discussion_r898496259\n    float concave = pos_nx.w - floor(pos_nx.w * 0.5) * 2.0;\n    float start = top_up_ny_start.w;\n    float y_ground = 1.0 - clamp(t + base, 0.0, 1.0);\n    float top_height = height;\n#ifdef TERRAIN\n    top_height = mix(max(c_ele + height, ele + base + 2.0), ele + height, float(centroid_pos.x == 0.0)) - ele;\n    y_ground += y_ground * 5.0 / max(3.0, top_height);\n#endif\n    v_ao = vec3(mix(concave, -concave, start), y_ground, h - ele);\n    NdotL *= (1.0 + 0.05 * (1.0 - top_up_ny.y) * u_ao[0]); // compensate sides faux ao shading contribution\n\n#ifdef PROJECTION_GLOBE_VIEW\n    top_height += u_height_lift;\n#endif\n    gl_Position.z -= (0.0000006 * (min(top_height, 500.) + 2.0 * min(base, 500.0) + 60.0 * concave + 3.0 * start)) * gl_Position.w;\n#endif\n\n#ifdef LIGHTING_3D_MODE\n    v_normal = normal;\n#else\n    v_lighting.rgb += clamp(NdotL * u_lightcolor, mix(vec3(0.0), vec3(0.3), 1.0 - u_lightcolor), vec3(1.0));\n    v_lighting *= u_opacity;\n#endif\n\n#ifdef FOG\n    v_fog_pos = fog_position(p);\n#endif\n}\n";

var hillshadePrepareFrag = "precision highp float;\n\nuniform highp sampler2D u_image;\nin vec2 v_pos;\nuniform vec2 u_dimension;\nuniform float u_zoom;\n\nfloat getElevation(vec2 coord) {\n    return texture(u_image, coord).r / 4.0;\n}\n\nvoid main() {\n    vec2 epsilon = 1.0 / u_dimension;\n\n    // queried pixels:\n    // +-----------+\n    // |   |   |   |\n    // | a | b | c |\n    // |   |   |   |\n    // +-----------+\n    // |   |   |   |\n    // | d |   | e |\n    // |   |   |   |\n    // +-----------+\n    // |   |   |   |\n    // | f | g | h |\n    // |   |   |   |\n    // +-----------+\n\n    float a = getElevation(v_pos + vec2(-epsilon.x, -epsilon.y));\n    float b = getElevation(v_pos + vec2(0, -epsilon.y));\n    float c = getElevation(v_pos + vec2(epsilon.x, -epsilon.y));\n    float d = getElevation(v_pos + vec2(-epsilon.x, 0));\n    float e = getElevation(v_pos + vec2(epsilon.x, 0));\n    float f = getElevation(v_pos + vec2(-epsilon.x, epsilon.y));\n    float g = getElevation(v_pos + vec2(0, epsilon.y));\n    float h = getElevation(v_pos + vec2(epsilon.x, epsilon.y));\n\n    // Here we divide the x and y slopes by 8 * pixel size\n    // where pixel size (aka meters/pixel) is:\n    // circumference of the world / (pixels per tile * number of tiles)\n    // which is equivalent to: 8 * 40075016.6855785 / (512 * pow(2, u_zoom))\n    // which can be reduced to: pow(2, 19.25619978527 - u_zoom).\n    // We want to vertically exaggerate the hillshading because otherwise\n    // it is barely noticeable at low zooms. To do this, we multiply this by\n    // a scale factor that is a function of zooms below 15, which is an arbitrary\n    // that corresponds to the max zoom level of Mapbox terrain-RGB tiles.\n    // See nickidlugash's awesome breakdown for more info:\n    // https://github.com/mapbox/mapbox-gl-js/pull/5286#discussion_r148419556\n\n    float exaggerationFactor = u_zoom < 2.0 ? 0.4 : u_zoom < 4.5 ? 0.35 : 0.3;\n    float exaggeration = u_zoom < 15.0 ? (u_zoom - 15.0) * exaggerationFactor : 0.0;\n\n    vec2 deriv = vec2(\n        (c + e + e + h) - (a + d + d + f),\n        (f + g + g + h) - (a + b + b + c)\n    ) / pow(2.0, exaggeration + (19.2562 - u_zoom));\n\n    glFragColor = clamp(vec4(\n        deriv.x / 2.0 + 0.5,\n        deriv.y / 2.0 + 0.5,\n        1.0,\n        1.0), 0.0, 1.0);\n}\n";

var fillExtrusionGroundEffectFrag = "uniform highp float u_ao_pass;\nuniform highp float u_opacity;\n\nuniform highp float u_flood_light_intensity;\nuniform highp vec3 u_flood_light_color;\n\nuniform highp float u_attenuation;\n\nuniform sampler2D u_fb;\nuniform float u_fb_size;\n\n#ifdef SDF_SUBPASS\nin highp vec2 v_pos;\nin highp vec4 v_line_segment;\nin highp float v_flood_light_radius_tile;\nin highp vec2 v_ao;\n\nfloat line_df(highp vec2 a, highp vec2 b, highp vec2 p) {\n    highp vec2 ba = b - a;\n    highp vec2 pa = p - a;\n    highp float r = clamp(dot(pa, ba) / dot(ba, ba), 0.0, 1.0);\n    return length(pa - r * ba);\n}\n\n#ifdef FOG\nin highp float v_fog;\n#endif // FOG\n#endif // SDF_SUBPASS\n\nvoid main() {\n// Note that these are used in only in draped mode. The simple clear to white is needed to ensure that the alpha channel is set to 1. \n// This is necessary because the subsequent steps in both ground flood light and AO\n// encode DF values in tandem with gl.MIN blending mode where a value of 0 indicates the effect is fully present.\n// Once an effect is rendered, it's necessary to mark the alpha channel correctly taking into account the original values (encoded in the texture) which \n// contain the layer emissive strength values. \n#ifdef CLEAR_SUBPASS\n    vec4 color = vec4(1.0);\n#ifdef CLEAR_FROM_TEXTURE\n    color = texture(u_fb, gl_FragCoord.xy / vec2(u_fb_size));\n#endif // CLEAR_FROM_TEXTURE\n    glFragColor = color;\n#else // CLEAR_SUBPASS\n#ifdef SDF_SUBPASS\n    highp float d = line_df(v_line_segment.xy, v_line_segment.zw, v_pos);\n    highp float effect_radius = mix(v_flood_light_radius_tile, v_ao.y, u_ao_pass);\n    d /= effect_radius;\n    d = min(d, 1.0);\n    d = 1.0 - pow(1.0 - d, u_attenuation);\n    highp float effect_intensity = mix(u_flood_light_intensity, v_ao.x, u_ao_pass);\n    highp float fog = 1.0;\n#ifdef FOG\n    fog = v_fog;\n#endif // FOG\n#ifdef RENDER_CUTOFF\n    fog *= v_cutoff_opacity;\n#endif // RENDER_CUTOFF\n    glFragColor = vec4(vec3(0.0), mix(1.0, d, effect_intensity * u_opacity * fog));\n#else // SDF_SUBPASS\nvec4 color = mix(vec4(u_flood_light_color, 1.0), vec4(vec3(0.0), 1.0), u_ao_pass);\n#ifdef OVERDRAW_INSPECTOR\n    color = vec4(1.0);\n#endif\n    glFragColor = color;\n#endif // !SDF_SUBPASS\nHANDLE_WIREFRAME_DEBUG;\n#endif // !CLEAR_SUBPASS\n}\n";

var fillExtrusionGroundEffectVert = "#include \"_prelude_fog.vertex.glsl\"\n\nin highp vec4 a_pos_end;\nin highp float a_angular_offset_factor;\nin highp float a_hidden_by_landmark;\n\n#ifdef SDF_SUBPASS\nout highp vec2 v_pos;\nout highp vec4 v_line_segment;\nout highp float v_flood_light_radius_tile;\nout highp vec2 v_ao;\n#ifdef FOG\nout highp float v_fog;\n#endif\n#endif\n\nuniform highp float u_flood_light_intensity;\n\nuniform highp mat4 u_matrix;\nuniform highp float u_ao_pass;\nuniform highp float u_meter_to_tile;\nuniform highp float u_edge_radius; // in tile coords\n\nuniform highp float u_dynamic_offset;\n\nuniform highp vec2 u_ao;\n\n#pragma mapbox: define highp float flood_light_ground_radius\n\nconst float TANGENT_CUTOFF = 4.0;\nconst float NORM = 32767.0;\n\nvoid main() {\n    #pragma mapbox: initialize highp float flood_light_ground_radius\n\n    vec2 p = a_pos_end.xy;\n    vec2 q = floor(a_pos_end.zw * 0.5);\n    vec2 start_bottom = a_pos_end.zw - q * 2.0;\n\n    float fl_ground_radius = flood_light_ground_radius;\n    fl_ground_radius = abs(flood_light_ground_radius);\n    float direction = flood_light_ground_radius < 0.0 ? -1.0 : 1.0;\n    float flood_radius_tile = fl_ground_radius * u_meter_to_tile;\n    vec2 v = normalize(q - p);\n    float ao_radius = u_ao.y / 3.5; // adjust AO radius slightly\n    float effect_radius = mix(flood_radius_tile, ao_radius, u_ao_pass) + u_edge_radius;\n\n    float angular_offset_factor = a_angular_offset_factor / NORM * TANGENT_CUTOFF;\n    float angular_offset = direction * angular_offset_factor * effect_radius;\n\n    float top = 1.0 - start_bottom.y;\n\n    float side = (0.5 - start_bottom.x) * 2.0;\n\n    vec2 extrusion_parallel = v * side * mix(u_dynamic_offset, angular_offset, top);\n\n    vec2 perp = vec2(v.y, -v.x);\n    vec2 extrusion_perp = direction * perp * effect_radius * top;\n\n    vec3 pos = vec3(mix(q, p, start_bottom.x), 0.0);\n    pos.xy += extrusion_parallel + extrusion_perp;\n\n#ifdef SDF_SUBPASS\n    v_pos = pos.xy;\n    // Shift the line segment against which we compute the signed distance values. \n    // This allows us to achieve pleasant results without having to add additional\n    // vertices when fill-extrusion-edge-radius is non-zero. \n    v_line_segment = vec4(p, q) + perp.xyxy * u_edge_radius;\n    v_flood_light_radius_tile = flood_radius_tile;\n    v_ao = vec2(u_ao.x, ao_radius);\n#ifdef FOG\n    v_fog_pos = fog_position(pos);\n    v_fog = 1.0 - fog(v_fog_pos);\n#endif\n#endif\n\n    float hidden_by_landmark = 0.0;\n#ifdef HAS_CENTROID\n    hidden_by_landmark = a_hidden_by_landmark;\n#endif\n\n    float isFloodlit = float(fl_ground_radius > 0.0 && u_flood_light_intensity > 0.0);\n    float hidden = mix(1.0 - isFloodlit, isFloodlit, u_ao_pass);\n    hidden += hidden_by_landmark;\n\n    gl_Position = mix(u_matrix * vec4(pos, 1.0), AWAY, float(hidden > 0.0));\n\n#ifdef RENDER_CUTOFF\n    v_cutoff_opacity = cutoff_opacity(u_cutoff_params, gl_Position.z);\n#endif\n}\n";

var hillshadePrepareVert = "uniform mat4 u_matrix;\nuniform vec2 u_dimension;\n\nin vec2 a_pos;\nin vec2 a_texture_pos;\n\nout vec2 v_pos;\n\nvoid main() {\n    gl_Position = u_matrix * vec4(a_pos, 0, 1);\n\n    highp vec2 epsilon = 1.0 / u_dimension;\n    float scale = (u_dimension.x - 2.0) / u_dimension.x;\n    v_pos = (a_texture_pos / 8192.0) * scale + epsilon;\n}\n";

var hillshadeFrag = "#include \"_prelude_fog.fragment.glsl\"\n#include \"_prelude_lighting.glsl\"\n\nuniform sampler2D u_image;\nin vec2 v_pos;\n\nuniform vec2 u_latrange;\nuniform vec2 u_light;\nuniform vec4 u_shadow;\nuniform vec4 u_highlight;\nuniform vec4 u_accent;\nuniform float u_emissive_strength;\n\nvoid main() {\n    vec4 pixel = texture(u_image, v_pos);\n\n    vec2 deriv = ((pixel.rg * 2.0) - 1.0);\n\n    // We divide the slope by a scale factor based on the cosin of the pixel's approximate latitude\n    // to account for mercator projection distortion. see #4807 for details\n    float scaleFactor = cos(radians((u_latrange[0] - u_latrange[1]) * (1.0 - v_pos.y) + u_latrange[1]));\n    // We also multiply the slope by an arbitrary z-factor of 1.25\n    float slope = atan(1.25 * length(deriv) / scaleFactor);\n    float aspect = deriv.x != 0.0 ? atan(deriv.y, -deriv.x) : PI / 2.0 * (deriv.y > 0.0 ? 1.0 : -1.0);\n\n    float intensity = u_light.x;\n    // We add PI to make this property match the global light object, which adds PI/2 to the light's azimuthal\n    // position property to account for 0deg corresponding to north/the top of the viewport in the style spec\n    // and the original shader was written to accept (-illuminationDirection - 90) as the azimuthal.\n    float azimuth = u_light.y + PI;\n\n    // We scale the slope exponentially based on intensity, using a calculation similar to\n    // the exponential interpolation function in the style spec:\n    // src/style-spec/expression/definitions/interpolate.js#L217-L228\n    // so that higher intensity values create more opaque hillshading.\n    float base = 1.875 - intensity * 1.75;\n    float maxValue = 0.5 * PI;\n    float scaledSlope = intensity != 0.5 ? ((pow(base, slope) - 1.0) / (pow(base, maxValue) - 1.0)) * maxValue : slope;\n\n    // The accent color is calculated with the cosine of the slope while the shade color is calculated with the sine\n    // so that the accent color's rate of change eases in while the shade color's eases out.\n    float accent = cos(scaledSlope);\n    // We multiply both the accent and shade color by a clamped intensity value\n    // so that intensities >= 0.5 do not additionally affect the color values\n    // while intensity values < 0.5 make the overall color more transparent.\n    vec4 accent_color = (1.0 - accent) * u_accent * clamp(intensity * 2.0, 0.0, 1.0);\n    float shade = abs(mod((aspect + azimuth) / PI + 0.5, 2.0) - 1.0);\n    vec4 shade_color = mix(u_shadow, u_highlight, shade) * sin(scaledSlope) * clamp(intensity * 2.0, 0.0, 1.0);\n    glFragColor = accent_color * (1.0 - shade_color.a) + shade_color;\n\n#ifdef LIGHTING_3D_MODE\n    glFragColor = apply_lighting_with_emission_ground(glFragColor, u_emissive_strength);\n#endif\n#ifdef FOG\n    glFragColor = fog_dither(fog_apply_premultiplied(glFragColor, v_fog_pos));\n#endif\n\n#ifdef OVERDRAW_INSPECTOR\n    glFragColor = vec4(1.0);\n#endif\n\n    HANDLE_WIREFRAME_DEBUG;\n}\n";

var hillshadeVert = "#include \"_prelude_fog.vertex.glsl\"\n\nuniform mat4 u_matrix;\n\nin vec2 a_pos;\nin vec2 a_texture_pos;\n\nout vec2 v_pos;\n\nvoid main() {\n    gl_Position = u_matrix * vec4(a_pos, 0, 1);\n    v_pos = a_texture_pos / 8192.0;\n\n#ifdef FOG\n    v_fog_pos = fog_position(a_pos);\n#endif\n}\n";

